import{_ as t,l as r,o as a,c as l,v as n,p as s,x as o,d,i as p,S as g}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"GLM-5","description":"","frontmatter":{"title":"GLM-5","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/glm-5.md","filePath":"llm/glm-5.md","lastUpdated":1789023840000}'),c={name:"llm/glm-5.md"};function m(h,e,A,E,B,M){const i=r("Mermaid");return a(),l("div",null,[e[1]||(e[1]=n('<h1 id="glm-5" tabindex="-1">GLM-5 <a class="header-anchor" href="#glm-5" aria-label="Permalink to &quot;GLM-5&quot;">​</a></h1><div class="epigraph"><p>相对 4.5，GLM-5 把规模从 355B（32B 激活）拉到 744B（40B 激活），预训练从 23T 加到 28.5T，并第一次接入 DeepSeek Sparse Attention，把部署成本压下去。</p><footer>—— Z.AI 文档，GLM-5；发布说明 GLM-5: From Vibe Coding to Agentic Engineering，2026-02-12</footer></div><p><a href="/llm/glm4-plus">GLM-4-Plus / GLM-4.5</a> 把开源 MoE 做到 355B/32B 与 ARC 后训练。2026 年 2 月 12 日智谱放出 <strong>GLM-5</strong>：定位从「会写代码、会前端」改成 <strong>Agentic Engineering</strong>——复杂系统工程与长程智能体。官方文档给出的规模句是总参 <strong>744B</strong>、激活 <strong>40B</strong>，预训练 <strong>28.5T</strong> token，并集成 <a href="/llm/deepseek-sparse-attention">DSA</a>。权重按 MIT 在 Hugging Face / ModelScope 开源，API 名 <code>glm-5</code>。本篇写 2 月这条旗舰底座；5.1 / 5.2 / 5.3 是后续检查点，能力与是否同底座以各篇发布说明为准，不把 5.3 的 1M 窗口回写成 5 的默认规格。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>4.5 已经能在 SWE-bench 一类仓库修补上打进开源前列，但真实工程是「从一句话到可运行系统」：拆任务、改后端、调试、预览、跨很多步仍不跑题。只加参数不够；需要能覆盖长程交互的异步 RL，以及把长上下文的服务成本压到可部署。4.5 的注意力仍偏稠密全量路径；V4 系已经证明 DSA 可以在几乎不掉长文质量的前提下砍 KV。GLM-5 要把这套稀疏注意力接到自己的 MoE 上，而不是再发一个只能 demo 的 1M 开关。</p><p>产品侧同时要接 Claude Code / OpenClaw 一类现成 harness，以及自有的 Z Code 多智能体闭环。评测主场因此是 SWE-bench Verified、Terminal Bench 2.0、BrowseComp、MCP-Atlas、τ²-Bench，而不是再刷一道 MMLU。</p><h3 id="文档窗口与后续快照不要混表" tabindex="-1">文档窗口与后续快照不要混表 <a class="header-anchor" href="#文档窗口与后续快照不要混表" aria-label="Permalink to &quot;文档窗口与后续快照不要混表&quot;">​</a></h3><p>Z.AI 的 GLM-5 型号页把上下文写成 <strong>200K</strong>、最大输出 <strong>128K</strong>，输入输出皆文本，并提供思考开关（<code>thinking.type</code> 默认 enabled）。这是 5 这条 API 的公开规格。后来的 5.1 强调更长地平线，5.3 文档出现过 1M 窗口、且写明与 5.2 <strong>同一底座、增益全来自后训练</strong>——那些句子属于后续篇。把 5.3 的 Coding Plan 积分制和网络安全评测抄进「GLM-5 发布日」，是错代。</p><p><span class="marginnote">发布日公开分数：SWE-bench Verified <strong>77.8</strong>、Terminal Bench 2.0 <strong>56.2</strong>，官方称为当时开源领先，并写在软件工程总体上超过 Gemini 3.0 Pro。内部 Claude Code 任务分布上相对 GLM-4.7 的前/后端与长程执行有大幅提升。具体对照快照以发布博文为准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>规模：355B/32B → 744B/40B，预训 23T → 28.5T。激活只从 32B 到 40B，总量几乎翻倍，走的是「容量进专家、费用走激活」的 MoE 账。文档把后训练增量写在自研 <strong>Slime</strong> 框架上：支撑更大模型与更复杂 RL，并提出异步智能体 RL，使模型能从长程交互里持续学，而不是只在短 rollout 上刷分。注意力第一次接入 DSA：官方句是长文质量近乎无损、部署成本显著下降、token 效率上升。专家个数、层数、是否仍为 4.5 的 160 专家 top-8，<strong>5 的型号页没有重开 4.5 报告那张表</strong>；未出现在 5 的官方说明里就不要用 4.5 的 96 头去填。</p><h3 id="从-vibe-coding-到工程闭环" tabindex="-1">从 vibe coding 到工程闭环 <a class="header-anchor" href="#从-vibe-coding-到工程闭环" aria-label="Permalink to &quot;从 vibe coding 到工程闭环&quot;">​</a></h3><p>发布叙事把模型写成系统架构师：与 Z Code 一起做任务分解、编码、调试预览的多智能体闭环，并支持把材料直接转成 docx / pdf / xlsx，在 Excel 里做原生插件。这是产品能力，不是新注意力公式。API 上思考可开关；温度示例用 1.0。Coding Plan 把模型接到 Claude Code、OpenCode、Cline 等，本地则走 vLLM / SGLang。</p>',13)),(a(),s(g,null,{default:o(()=>[p(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20P45%5B%22GLM-4.5%EF%BC%9A355B%20%2F%2032B%EF%BC%8C23T%22%5D%20--%3E%20PT%5B%22%E9%A2%84%E8%AE%AD%E5%8A%A0%E5%88%B0%2028.5T%22%5D%0A%20%20PT%20--%3E%20MOE%5B%22744B%20%2F%2040B%20MoE%22%5D%0A%20%20MOE%20--%3E%20DSA%5B%22%E6%8E%A5%E5%85%A5%20DSA%20%E7%A8%80%E7%96%8F%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20DSA%20--%3E%20SLIME%5B%22Slime%EF%BC%9A%E5%BC%82%E6%AD%A5%E6%99%BA%E8%83%BD%E4%BD%93%20RL%22%5D%0A%20%20SLIME%20--%3E%20G5%5B%22GLM-5%22%5D%0A%20%20G5%20--%3E%20API%5B%22api.z.ai%20%C2%B7%20glm-5%22%5D%0A%20%20G5%20--%3E%20OSS%5B%22HF%20%2F%20ModelScope%20%C2%B7%20MIT%22%5D%0A%20%20G5%20--%3E%20ZC%5B%22Z%20Code%20%2F%20Coding%20Plan%20harness%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n('<p>Agentic Engineering 被定义成：不止生成代码或完成单步任务，而要在长地平线上保持目标、管理中间资源、协调工具、解开多步依赖而不散焦。BrowseComp 测检索综合，MCP-Atlas 测工具与多步执行，τ²-Bench 测多工具编排——三条一起才构成「能当工程师」而不是「能补丁函数」。</p><p><span class="marginnote">5.3 发布文写「Scaling post-training is all we did」，并报网络安全能力随 RL 冒出。那是 2026-08 的后训练故事，证明 5 系底座还能继续榨；不要把 CyberGym 分数写进 2 月的 GLM-5 默认列。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>激活 40B 决定单 token FLOPs，744B 决定装载与专家并行。相对 4.5 多出来的主要是专家容量与 5.5T 预训 token，用来抬通用智力，而不是把思考模型与聊天模型拆成两套权。DSA 把注意力分数的计算从全量键改成稀疏索引再精算，长上下文的 KV 与预填充随可索引集合缩小——这是部署句「成本大幅下降」的机制内容。具体 indexer 是否与 V3.2 逐项相同，5 的文档没有展开，正确句子是「集成 DSA」，不要默写 DeepSeek 报告里的超参。</p><p>异步 RL 改的是数据时间：智能体环境里的轨迹很长，同步等待会让 GPU 空转；Slime 把训练与环境解耦，使长程信用分配成为可能。没有算法伪代码就不能写成 CISPO 或 GRPO 的改写；官方只保证「异步智能体 RL」这一层级。思考默认开启，简单寒暄也会先花内部 token——产品必须允许 <code>disabled</code>，否则办公短请求会被写成内心独白。</p><h3 id="和-4-5、和闭源-opus-档" tabindex="-1">和 4.5、和闭源 Opus 档 <a class="header-anchor" href="#和-4-5、和闭源-opus-档" aria-label="Permalink to &quot;和 4.5、和闭源 Opus 档&quot;">​</a></h3><p>4.5 报告有完整层表与 Muon、MTP；5 的公开文本以规模、DSA、Slime、工程评测为主。对齐句是「真实编程体验接近 Claude Opus 4.5」，不是参数量对齐。SWE 77.8 是开源主场，不是证明可以替换所有 Opus 工作流：脚手架、提示、是否思考，换设置则不可比。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>5 的官方窗口是 200K，不是百万。后续快照若拉长，应另引文档。层表未在 5 的型号页完整重印，专家数公开信息有限。MIT 权重可自托管，但 744B 仍是多机对象；不要把「开源」写成「笔记本可跑」。思考开关与后来 5.2+ 的 <code>reasoning_effort</code> 枚举不是同一 API：5 的示例只有 enabled / disabled。安全与内容策略走平台条款；开源权重的红队责任在部署方。</p><p>不要用 Artificial Analysis 上「某日第四」的复合分代替 SWE / Terminal 主表。不要把 GLM-5-Turbo / 5V-Turbo 的模态写成 5 语言旗舰的默认。Z Code 多智能体与 Excel 插件是产品编排，不能反推 MoE 里存在「表格专家」。</p><p><span class="marginnote">出处：Z.AI，<em>GLM-5: From Vibe Coding to Agentic Engineering</em>（2026-02-12）；<em>GLM-5</em> 型号文档。5.1 / 5.3 见各自博文，不合并进本篇规格。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GLM-5（2026-02-12）是 744B/40B 的开源 MoE，预训 28.5T，定位 Agentic Engineering。</li><li>相对 4.5：更大 MoE、DSA、Slime 异步智能体 RL；API 窗口 200K / 输出 128K。</li><li>发布日主表是 SWE-bench Verified 77.8 与 Terminal Bench 2.0 56.2；层表未完整重开。</li><li>后续 5.x 后训练快照不得回写为 5 的默认窗口或安全评测。</li><li>出处：z.ai 发布博文与 GLM-5 文档。</li></ul>',13))])}const C=t(c,[["render",m]]);export{S as __pageData,C as default};
